code.nochesobreelcanal:
const w = K.world3d(root, T0, T1, {ground: 'atlantic', sky: 'tormenta', look: 'clean', haze: 5});
w.shot(T0, [-1.5, 50.2], {dist: 820, pitch: 65, yaw: 0});
w.shot(T0 + 0.15, [-1.5, 50.2], {dist: 300, pitch: 28, yaw: -8, dur: T1 - T0 - 0.15});
w.drift(0.035);

// Capas 2D de respaldo: el canal y la tormenta permanecen legibles incluso si el render 3D es tenue.
const scene = K.svg(root, 0, 0, 1920, 1080);
scene.style.pointerEvents = 'none';
K.shape(scene, 'rect', {x: 0, y: 0, width: 1920, height: 1080, fill: '#18232D'});
const cloudGroup = K.shape(scene, 'g', {});
K.shape(cloudGroup, 'path', {d: 'M0 0H1920V244 C1740 221 1640 272 1480 246 C1300 218 1180 270 1010 244 C820 214 690 273 520 240 C330 207 170 271 0 236Z', fill: '#35434D', opacity: 0.84});
K.shape(cloudGroup, 'path', {d: 'M0 112 C135 71 250 125 386 89 C526 52 640 119 773 83 C913 45 1035 119 1171 84 C1319 47 1440 121 1572 78 C1705 36 1815 88 1920 56 V314 C1782 283 1657 335 1515 300 C1354 261 1231 329 1075 295 C920 261 781 326 622 290 C459 252 332 324 174 288 C104 272 49 293 0 303Z', fill: '#46545C', opacity: 0.56});
K.shape(cloudGroup, 'path', {d: 'M0 258 C176 218 293 282 449 244 C600 207 729 276 883 238 C1047 198 1175 274 1330 235 C1488 196 1619 263 1760 224 C1828 206 1880 211 1920 202 V455 C1760 419 1622 477 1450 439 C1270 399 1134 470 962 432 C785 392 635 469 460 428 C286 388 152 457 0 421Z', fill: '#293741', opacity: 0.9});
K.shape(scene, 'path', {d: 'M0 474 C280 458 490 483 735 466 C1000 446 1203 485 1450 461 C1650 442 1790 464 1920 448 V1080 H0Z', fill: '#101A23'});
K.shape(scene, 'path', {d: 'M0 491 C340 475 548 501 820 482 C1110 462 1384 500 1624 478 C1745 467 1830 474 1920 463 L1920 544 C1700 526 1540 553 1310 532 C1060 510 875 551 634 528 C398 506 190 543 0 524Z', fill: '#263640', opacity: 0.94});
K.shape(scene, 'path', {d: 'M0 502 C390 484 605 514 885 493 C1150 473 1410 513 1650 490 C1765 480 1850 488 1920 476', fill: 'none', stroke: '#AAB6BA', 'stroke-width': 3, opacity: 0.25});
K.show(scene, T0 + 0.02, {dur: 0.32, ease: 'outCubic'});

// Nubes desplazadas por el viento y olas que siguen moviéndose durante toda la escena.
const waves = [];
for (let i = 0; i < 11; i++) {
  waves.push(K.shape(scene, 'path', {d: '', fill: 'none', stroke: i % 3 === 0 ? '#AAB6BA' : '#71828A', 'stroke-width': i % 3 === 0 ? 2.4 : 1.5, 'stroke-linecap': 'round', opacity: i % 3 === 0 ? 0.30 : 0.18}));
}
K.onFrame((t) => {
  const e = Math.max(0, t - T0);
  cloudGroup.setAttribute('transform', `translate(${(-12 - e * 8).toFixed(1)} ${(Math.sin(e * 0.55) * 3).toFixed(1)})`);
  for (let i = 0; i < waves.length; i++) {
    const y = 563 + i * 49;
    let d = `M-30 ${y}`;
    for (let x = 0; x <= 1950; x += 130) {
      const yy = y + Math.sin(x * 0.007 + e * (1.6 + i * 0.045) + i * 1.7) * (4 + (i % 4) * 2.2);
      d += ` L${x} ${yy.toFixed(1)}`;
    }
    waves[i].setAttribute('d', d);
  }
});

const card = K.box(root, 128, 126, {w: 610, h: 222, style: {boxSizing: 'border-box', padding: '24px 30px', background: 'rgba(24,35,45,0.94)', borderLeft: '6px solid #D4A017', boxShadow: '0 12px 36px rgba(0,0,0,0.28)'}});
K.box(card, 30, 18, {w: 520, h: 44, cls: 'label', html: 'PARTE MILITAR', style: {fontSize: '36px', color: '#D4A017', letterSpacing: '3px'}});
K.box(card, 30, 74, {w: 520, h: 62, cls: 'label', html: '05 JUN 1944', style: {fontSize: '52px', color: '#F2F0E8', letterSpacing: '1px'}});
K.box(card, 30, 146, {w: 540, h: 46, cls: 'label', html: 'CANAL DE LA MANCHA', style: {fontSize: '36px', color: '#AAB6BA', letterSpacing: '1px'}});
K.show(card, K.cue('noche'), {dur: 0.55, from: {x: -18, y: 10}, ease: 'outCubic'});

// La lluvia entra justo con «temporal» y cruza oblicuamente el encuadre hasta el final.
const rain = K.svg(root, 0, 0, 1920, 1080);
rain.style.pointerEvents = 'none';
rain.style.opacity = '0';
const streaks = [];
for (let i = 0; i < 88; i++) {
  streaks.push(K.shape(rain, 'line', {x1: 0, y1: 0, x2: 27, y2: 43, stroke: '#C1C9C9', 'stroke-width': i % 4 === 0 ? 2.1 : 1.3, 'stroke-linecap': 'round', opacity: i % 4 === 0 ? 0.38 : 0.23}));
}
const rainAt = K.cue('temporal');
K.show(rain, rainAt, {dur: 0.18, ease: 'outCubic'});
w.fx('rain', [-1.5, 50.2], rainAt, T1, {size: 1.5});
K.onFrame((t) => {
  const e = Math.max(0, t - rainAt);
  for (let i = 0; i < streaks.length; i++) {
    const x = ((i * 173 + e * 420) % 2040) - 60;
    const y = ((i * 97 + e * 650) % 1190) - 55;
    streaks[i].setAttribute('x1', x);
    streaks[i].setAttribute('y1', y);
    streaks[i].setAttribute('x2', x + 27);
    streaks[i].setAttribute('y2', y + 43);
  }
});

code.presioneneleste:
const w = K.world3d(root, T0, T1, {ground: 'europe', sky: 'plomizo', look: 'clean', haze: 5});
w.shot(T0, [24, 53], {dist: 1280, pitch: 64, yaw: -10});
w.shot(K.cue('pedía'), [15, 52], {dist: 1200, pitch: 64, yaw: -10, dur: 2.4});
w.shot(K.cue('segundo'), [8, 51], {dist: 1120, pitch: 64, yaw: -10, dur: 1.5});
w.drift(0.08);

// Mapa cartográfico legible sobre el mapa 3D: permanece presente toda la escena.
const layer = K.box(root, 0, 0, {w: 1920, h: 1080, style: {backgroundColor: 'transparent', pointerEvents: 'none'}});
K.box(layer, 82, 178, {w: 1756, h: 660, style: {backgroundColor: 'rgba(24,35,45,.74)', border: '1px solid rgba(170,182,186,.35)', borderRadius: '6px'}});
const m = K.map.world(layer, {x: 100, y: 182, w: 1720, h: 650, projection: 'naturalEarth1', focus: [[-13, 34], [43, 72]], fill: '#35434D', stroke: '#78858A'});
K.show(layer, T0, {dur: 0.18, ease: 'outCubic'});

const title = K.box(root, 112, 70, {w: 1000, h: 104, cls: 'title', html: 'PRESIÓN EN EL ESTE', style: {fontSize: '86px', color: 'var(--ink)', letterSpacing: '2px', textShadow: '0 3px 16px rgba(0,0,0,.55)'}});
const titleRule = K.box(root, 116, 176, {w: 128, h: 5, style: {backgroundColor: '#D4A017', borderRadius: '3px'}});
K.show(title, T0, {from: {y: 12}, dur: 0.35, ease: 'outCubic'});
K.show(titleRule, T0 + 0.08, {from: {x: -12}, dur: 0.3, ease: 'outCubic'});

const svg = K.svg(layer, 100, 182, 1720, 650);
const projectPath = points => points.map((p, i) => {
  const q = m.project(p);
  return (i ? 'L' : 'M') + q[0].toFixed(1) + ' ' + q[1].toFixed(1);
}).join(' ');

// Banda amplia del frente oriental, con una línea central discreta.
const frontT = K.cue('soportaba');
const frontD = projectPath([[17, 61], [21, 58], [24, 55], [28, 52], [32, 49], [35, 46]]);
const branchD = projectPath([[19, 49], [23, 51], [27, 53], [31, 55], [35, 57]]);
const frontBand = K.shape(svg, 'path', {d: frontD, fill: 'none', stroke: '#7B7B7B', strokeWidth: 30, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.72});
const frontBranch = K.shape(svg, 'path', {d: branchD, fill: 'none', stroke: '#7B7B7B', strokeWidth: 16, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.56});
const frontCore = K.shape(svg, 'path', {d: frontD, fill: 'none', stroke: '#AAB6BA', strokeWidth: 4, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.9});
K.show(frontBand, frontT, {dur: 0.55, ease: 'outCubic'});
K.show(frontBranch, frontT + 0.12, {dur: 0.5, ease: 'outCubic'});
K.draw(frontCore, frontT + 0.08, 0.9);
w.route([[17, 61], [21, 58], [24, 55], [28, 52], [32, 49], [35, 46]], frontT, 1.1, {color: '#7b7b7b', arc: 0});

// Ruta de comunicación hacia el oeste.
const westT = K.cue('pedía');
const westD = projectPath([[31, 54], [24, 53], [17, 52], [10, 51], [3, 50]]);
const westUnder = K.shape(svg, 'path', {d: westD, fill: 'none', stroke: '#D4A017', strokeWidth: 12, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.28});
const westLine = K.shape(svg, 'path', {d: westD, fill: 'none', stroke: '#D4A017', strokeWidth: 5, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 1});
K.show(westUnder, westT, {dur: 0.4, ease: 'outCubic'});
K.draw(westLine, westT + 0.08, 1.15);
w.route([[31, 54], [24, 53], [17, 52], [10, 51], [3, 50]], westT, 1.2, {color: '#d4a017', arc: 0});

// Dos líneas aliadas convergen visualmente al mencionarse el segundo frente.
const convergeT = K.cue('segundo');
const d1 = projectPath([[11, 59], [7, 56], [3, 53], [-1, 50]]);
const d2 = projectPath([[11, 44], [7, 46], [3, 48], [-1, 50]]);
const c1base = K.shape(svg, 'path', {d: d1, fill: 'none', stroke: '#3D6EA8', strokeWidth: 10, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.28});
const c2base = K.shape(svg, 'path', {d: d2, fill: 'none', stroke: '#3D6EA8', strokeWidth: 10, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 0.28});
const c1 = K.shape(svg, 'path', {d: d1, fill: 'none', stroke: '#3D6EA8', strokeWidth: 5, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 1});
const c2 = K.shape(svg, 'path', {d: d2, fill: 'none', stroke: '#3D6EA8', strokeWidth: 5, strokeLinecap: 'round', strokeLinejoin: 'round', opacity: 1});
K.show([c1base, c2base], convergeT, {dur: 0.45, ease: 'outCubic'});
K.draw(c1, convergeT + 0.05, 0.85);
K.draw(c2, convergeT + 0.05, 0.85);
w.route([[11, 59], [7, 56], [3, 53], [-1, 50]], convergeT, 0.9, {color: '#3d6ea8', arc: 0});
w.route([[11, 44], [7, 46], [3, 48], [-1, 50]], convergeT, 0.9, {color: '#3d6ea8', arc: 0});

const endpoint = (coord, color, t) => {
  const p = m.project(coord);
  const halo = K.shape(svg, 'circle', {cx: p[0], cy: p[1], r: 14, fill: color, opacity: 0.24});
  const dot = K.shape(svg, 'circle', {cx: p[0], cy: p[1], r: 6, fill: color, stroke: '#F2F0E8', strokeWidth: 2});
  K.show(halo, t, {from: {scale: 0.6}, dur: 0.35, ease: 'outCubic'});
  K.show(dot, t, {from: {scale: 0.6}, dur: 0.35, ease: 'outCubic'});
};
endpoint([31, 54], '#D4A017', westT);
endpoint([-1, 50], '#3D6EA8', convergeT);

const frontLabel = K.box(layer, 128, 224, {w: 400, h: 48, cls: 'label', html: 'FRANJA DEL FRENTE', style: {fontSize: '34px', color: '#F2F0E8', letterSpacing: '1px', textShadow: '0 2px 10px rgba(0,0,0,.8)'}});
const routeLabel = K.box(layer, 1320, 754, {w: 430, h: 46, cls: 'label', html: 'RUTA HACIA EL OESTE', style: {fontSize: '32px', color: '#D4A017', letterSpacing: '1px', textShadow: '0 2px 10px rgba(0,0,0,.8)'}});
const convergeLabel = K.box(layer, 122, 774, {w: 310, h: 44, cls: 'label', html: 'LÍNEAS ALIADAS', style: {fontSize: '32px', color: '#78A5D4', letterSpacing: '1px', textShadow: '0 2px 10px rgba(0,0,0,.8)'}});
K.show(frontLabel, frontT + 0.2, {from: {y: 8}, dur: 0.35, ease: 'outCubic'});
K.show(routeLabel, westT + 0.15, {from: {y: 8}, dur: 0.35, ease: 'outCubic'});
K.show(convergeLabel, convergeT + 0.2, {from: {y: 8}, dur: 0.35, ease: 'outCubic'});

code.dimensiondeldiad:
root.style.perspective = '1600px';

const w = K.world3d(root, T0, T1, {
  ground: 'europe', sky: 'plomizo', look: 'clean', haze: 4
});
w.shot(T0, [-1.2, 50.35], {dist: 430, pitch: 42, yaw: -8});
w.shot(T0 + 1.0, [-1.2, 50.15], {dist: 760, pitch: 60, yaw: -8, dur: 2.5});
w.drift(0.06);

// El mapa real mantiene la geografía legible; el mar deja respirar la maqueta 3D.
const mapLayer = K.box(root, 0, 0, {
  w: 1920, h: 880,
  style: {opacity: 0, pointerEvents: 'none', backgroundColor: 'rgba(24,35,45,.18)'}
});
const m = K.map.world(mapLayer, {
  x: 90, y: 94, w: 1740, h: 730,
  projection: 'naturalEarth1', focus: [[-6, 48], [4, 53]],
  fill: '#35434D', stroke: '#AAB6BA'
});
K.show(mapLayer, T0 + 0.08, {dur: 0.55, ease: 'outCubic'});
K.anim(mapLayer, T0 + 0.6, {scale: [1, 1.012]}, T1 - T0 - 1.1, 'inOutSine');

const mapSvg = K.svg(mapLayer, 90, 94, 1740, 730);
const routePoints = [
  [[-2.25, 50.75], [-2.0, 50.38], [-1.55, 49.88]],
  [[-1.15, 50.78], [-1.1, 50.42], [-1.2, 49.82]],
  [[0.05, 50.76], [-0.35, 50.34], [-0.7, 49.82]]
];
const routeColors = ['#3d6ea8', '#D4A017', '#AAB6BA'];
routePoints.forEach((line, i) => {
  const [a, mid, b] = line.map(ll => m.project(ll));
  const path = K.shape(mapSvg, 'path', {
    d: `M ${a[0]} ${a[1]} Q ${mid[0]} ${mid[1]} ${b[0]} ${b[1]}`,
    fill: 'none', stroke: routeColors[i], strokeWidth: 4,
    strokeLinecap: 'round', strokeDasharray: '9 11'
  });
  K.draw(path, K.cue('dia') + 0.2 + i * 0.18, 1.35);
});

const label = (text, x, y, wBox, color = K.palette.ink, size = 36) => {
  const el = K.box(mapLayer, x, y, {
    w: wBox, h: 52, cls: 'label', html: text,
    style: {fontSize: `${size}px`, color, letterSpacing: '2px', textShadow: '0 2px 8px rgba(0,0,0,.45)'}
  });
  K.show(el, T0 + 0.12, {from: {y: 8}, dur: 0.48, ease: 'outCubic'});
  return el;
};
const placeTag = label('CANAL · 1944', 118, 112, 420, K.palette.ink, 36);
const normandy = m.project([-1.2, 49.8]);
const normandyTag = label('NORMANDÍA', 90 + normandy[0] + 28, 94 + normandy[1] + 18, 330, K.palette.accent, 36);

// Balizas discretas y flotas esquemáticas, visibles sobre la ruta sin ocultar el mapa.
const fleetT = K.cue('mayor');
const fleetPoints = [
  [-2.02, 50.45], [-1.78, 50.55], [-1.52, 50.43], [-1.24, 50.56], [-0.96, 50.43],
  [-1.88, 50.17], [-1.58, 50.22], [-1.28, 50.12], [-0.99, 50.2], [-0.72, 50.1]
];
fleetPoints.forEach((ll, i) => {
  const p = m.project(ll);
  const x = 90 + p[0], y = 94 + p[1];
  const halo = K.el(mapLayer, 'div', {style: {
    position: 'absolute', left: `${x - 24}px`, top: `${y - 24}px`,
    width: '48px', height: '48px', borderRadius: '50%',
    border: `2px solid ${i % 3 === 0 ? '#3d6ea8' : '#D4A017'}`,
    background: 'rgba(24,35,45,.72)', boxSizing: 'border-box'
  }});
  const ship = K.icon(mapLayer, 'ship', x - 18, y - 18, 36, {
    color: i % 3 === 0 ? '#8eb8e3' : '#F2F0E8', stroke: 2.2
  });
  K.show(halo, fleetT + i * 0.075, {from: {scale: 0.55}, dur: 0.42, ease: 'outCubic'});
  K.show(ship, fleetT + i * 0.075, {from: {y: 10, scale: 0.72}, dur: 0.42, ease: 'outBack'});
});

// Repliegue a una mesa de planificación despejada; la superficie permanece hasta el final.
const foldT = K.cue('volver');
const table = K.box(root, 0, 0, {w: 1920, h: 880, style: {
  opacity: 0, backgroundColor: '#35434D',
  backgroundImage: 'linear-gradient(135deg, rgba(255,255,255,.025), transparent 48%, rgba(0,0,0,.09))',
  transformOrigin: 'right center', boxSizing: 'border-box'
}});
const sheet = K.box(table, 150, 94, {w: 1620, h: 680, style: {
  backgroundColor: '#e8e2d4',
  backgroundImage: 'linear-gradient(rgba(53,67,77,.045) 1px, transparent 1px), linear-gradient(90deg, rgba(53,67,77,.035) 1px, transparent 1px), linear-gradient(135deg, #eee9dc, #ded7c7)',
  backgroundSize: '48px 48px, 48px 48px, 100% 100%',
  border: '1px solid rgba(255,255,255,.55)',
  boxShadow: '0 18px 46px rgba(0,0,0,.28)', boxSizing: 'border-box'
}});
for (const [x, y, sx, sy] of [[18, 18, 1, 1], [1584, 18, -1, 1], [18, 644, 1, -1], [1584, 644, -1, -1]]) {
  K.box(sheet, x, y, {w: 34, h: 3, style: {
    backgroundColor: 'rgba(53,67,77,.22)', transform: `scaleX(${sx})`,
    transformOrigin: sx < 0 ? 'right center' : 'left center'
  }});
  K.box(sheet, x, y, {w: 3, h: 34, style: {
    backgroundColor: 'rgba(53,67,77,.22)', transform: `scaleY(${sy})`,
    transformOrigin: sy < 0 ? 'center bottom' : 'center top'
  }});
}
// Una línea central tenue sugiere el pliegue físico de la hoja, sin añadir anotaciones.
K.box(sheet, 809, 24, {w: 1, h: 632, style: {backgroundColor: 'rgba(53,67,77,.07)'}});
K.hide(mapLayer, foldT, {dur: 0.45, to: {y: -8}});
K.show(table, foldT, {from: {x: 90, rotate: -1}, dur: 0.72, ease: 'inOutSine'});
K.anim(table, foldT, {rotateY: [-72, 0], translateX: [120, 0]}, 0.72, 'inOutSine');
w.shot(foldT, [-1.2, 50.15], {dist: 850, pitch: 66, yaw: -8, dur: 0.85});

code.olasycostafrancesa:
const p = K.palette;
const w = K.world3d(root, T0, T1, {ground: 'none', sky: 'tormenta', look: 'clean', haze: 6});
w.shot(T0, {x: 0, z: -12}, {dist: 118, pitch: 8, yaw: 0, h: 13});
w.shot(K.cue('agua'), {x: 0, z: 22}, {dist: 100, pitch: 10, yaw: 0, h: 14, dur: 3.1});
w.shot(K.cue('relajan'), {x: 0, z: 43}, {dist: 76, pitch: 10, yaw: 0, h: 14, dur: 2.2});
w.shot(K.cue('nadie'), {x: 0, z: 12}, {dist: 108, pitch: 8, yaw: 0, h: 13, dur: 2.4});
w.drift(0.08);
w.add('coast', {x: 0, z: 34}, {beach: true, bluff: true, cliff: true});
w.add('bunker', {x: -13, z: 61}, {scale: 1.15});
w.add('pillbox', {x: 17, z: 64}, {scale: 1.05});
w.add('hedgehog', {x: -5, z: 43}, {scale: 1.1});
w.add('hedgehog', {x: 10, z: 46}, {scale: 1.0});
w.add('stake', {x: 24, z: 48}, {scale: 1.05});
for (const [x, z, s] of [[-9, 54, 0.9], [-4, 57, 0.85], [4, 56, 0.9]]) {
  w.add('soldier', {x, z}, {scale: s, t: K.cue('soldados')});
}

// Capa ilustrada persistente: asegura que tormenta, mar y costa sigan legibles durante todo el plano.
const s = K.svg(root, 0, 0, 1920, 1080);
const base = [];
base.push(K.shape(s, 'path', {d: 'M0 470 Q250 445 470 470 T900 462 Q1180 450 1400 470 T1920 450 L1920 860 L0 860 Z'}, {fill: '#35434D', opacity: 0}));
base.push(K.shape(s, 'path', {d: 'M780 480 Q970 435 1110 452 Q1270 416 1410 445 Q1540 405 1690 437 Q1830 410 1920 423 L1920 570 Q1760 553 1610 572 Q1430 584 1280 560 Q1100 540 950 565 L780 580 Z'}, {fill: '#293740', opacity: 0}));
base.push(K.shape(s, 'path', {d: 'M890 552 Q1100 523 1270 548 Q1470 579 1650 542 Q1810 517 1920 536 L1920 660 Q1740 643 1600 662 Q1410 680 1230 640 Q1040 603 890 636 Z'}, {fill: '#35434D', opacity: 0}));
base.push(K.shape(s, 'path', {d: 'M0 510 Q230 490 430 514 T840 504 L840 860 L0 860 Z'}, {fill: '#24313A', opacity: 0}));
K.show(base, T0 + 0.1, {dur: 0.8, ease: 'outCubic'});

// Puesto defensivo bajo cubierta, en la costa francesa.
const fort = [];
fort.push(K.shape(s, 'path', {d: 'M1330 559 L1350 526 Q1368 504 1401 501 L1530 501 Q1564 507 1585 537 L1598 566 L1580 582 L1340 582 Z'}, {fill: '#18232D', stroke: '#11191E', strokeWidth: 4, opacity: 0}));
fort.push(K.shape(s, 'path', {d: 'M1404 524 L1519 524 L1536 550 L1390 550 Z'}, {fill: '#11191E', opacity: 0}));
fort.push(K.shape(s, 'path', {d: 'M1300 509 Q1450 475 1610 513 L1594 527 Q1450 495 1312 526 Z'}, {fill: '#202C34', opacity: 0}));
fort.push(K.shape(s, 'line', {x1: 1312, y1: 526, x2: 1594, y2: 527}, {stroke: '#AAB6BA', strokeWidth: 3, opacity: 0}));
K.show(fort, K.cue('francia'), {from: {y: 12}, dur: 0.75, ease: 'outCubic'});

// Obstáculos costeros discretos en silueta, detrás de la espuma.
const obstacles = [];
for (const [x, y, h] of [[1035, 596, 39], [1140, 610, 47], [1688, 600, 42], [1780, 615, 50]]) {
  obstacles.push(K.shape(s, 'line', {x1: x - 18, y1: y + h, x2: x + 18, y2: y}, {stroke: '#18232D', strokeWidth: 8, strokeLinecap: 'round', opacity: 0}));
  obstacles.push(K.shape(s, 'line', {x1: x + 18, y1: y + h, x2: x - 18, y2: y}, {stroke: '#18232D', strokeWidth: 8, strokeLinecap: 'round', opacity: 0}));
  obstacles.push(K.shape(s, 'line', {x1: x - 23, y1: y + h * 0.52, x2: x + 23, y2: y + h * 0.52}, {stroke: '#18232D', strokeWidth: 6, strokeLinecap: 'round', opacity: 0}));
}
K.show(obstacles, K.cue('francia'), {dur: 0.7, stagger: 0.025, ease: 'outCubic'});

// Figuras anónimas de espaldas, protegidas bajo el alero y mirando al mar.
const people = [];
for (const x of [1410, 1470, 1530]) {
  people.push(K.shape(s, 'circle', {cx: x, cy: 566, r: 11}, {fill: '#18232D', opacity: 0}));
  people.push(K.shape(s, 'path', {d: `M${x-12} 580 Q${x} 574 ${x+12} 580 L${x+16} 617 L${x+7} 619 L${x+5} 603 L${x+2} 641 L${x-5} 641 L${x-5} 603 L${x-11} 619 L${x-19} 617 Z`}, {fill: '#18232D', opacity: 0}));
  people.push(K.shape(s, 'path', {d: `M${x-10} 586 L${x-23} 600 M${x+10} 586 L${x+22} 600`}, {fill: 'none', stroke: '#18232D', strokeWidth: 6, strokeLinecap: 'round', opacity: 0}));
}
K.show(people, K.cue('soldados'), {from: {y: 7}, dur: 0.7, stagger: 0.045, ease: 'outCubic'});

// Mar agitado, con crestas en varias profundidades para conservar movimiento a ras del agua.
const waves = [];
for (let j = 0; j < 7; j++) {
  const y = 555 + j * 43;
  const d = `M0 ${y} Q120 ${y-18} 240 ${y} T480 ${y} T720 ${y} T960 ${y} T1200 ${y} T1440 ${y} T1680 ${y} T1920 ${y}`;
  waves.push(K.shape(s, 'path', {d}, {fill: 'none', stroke: j < 3 ? '#AAB6BA' : '#18232D', strokeWidth: j < 3 ? 4 : 3, opacity: 0}));
}
K.show(waves, T0 + 0.1, {dur: 0.65, stagger: 0.05, ease: 'outCubic'});

// Lluvia diagonal animada, visible desde el comienzo y durante todo el plano.
const rng = K.rand(1944);
const drops = [];
for (let i = 0; i < 96; i++) {
  const x = rng() * 2050 - 65;
  const y = rng() * 780 + 55;
  const el = K.shape(s, 'line', {x1: x, y1: y, x2: x - 22, y2: y + 43}, {stroke: '#AAB6BA', strokeWidth: i % 4 === 0 ? 2.5 : 1.7, opacity: 0});
  drops.push({x, y, el});
}
K.show(drops.map(d => d.el), T0 + 0.1, {dur: 0.6, stagger: 0.004, ease: 'outCubic'});

K.onFrame(t => {
  if (t < T0 || t > T1) return;
  const e = t - T0;
  for (const d of drops) {
    const x = ((d.x - e * 205 + 65) % 2050 + 2050) % 2050 - 65;
    const y = 55 + ((d.y - 55 + e * 130) % 780);
    d.el.setAttribute('x1', x);
    d.el.setAttribute('y1', y);
    d.el.setAttribute('x2', x - 22);
    d.el.setAttribute('y2', y + 43);
  }
  for (let j = 0; j < waves.length; j++) {
    const baseY = 555 + j * 43;
    let d = `M0 ${baseY}`;
    for (let x = 48; x <= 1920; x += 48) {
      const y = baseY + Math.sin(x * 0.012 + e * (1.25 + j * 0.11) + j * 1.6) * (9 + j * 1.7);
      d += ` L${x} ${y.toFixed(1)}`;
    }
    waves[j].setAttribute('d', d);
  }
});

const slug = K.box(root, 118, 108, {w: 520, h: 48, cls: 'label', html: 'NORMANDÍA  /  1944', style: {fontSize: '34px', letterSpacing: '3px', color: p.ink, opacity: 0}});
