code.francia1940:
const paper = '#D8D0BC';
const ink = '#343B3C';
const muted = '#817C70';
const mapX = 100, mapY = 145, mapW = 1720, mapH = 590;
const cueAt = (word, fallback) => K.clamp(K.cue(word, {fallback}), T0 + 0.1, T1 - 0.1);
const arrivalCue = cueAt('conquistado', T0 + 2.4);
const franceCue = cueAt('Francia', T0 + 3.15);
const sixCue = cueAt('seis', T0 + 4.33);
const occupiedCue = cueAt('ocupacion', T0 + 9.1);

// Papel permanente: el mapa y su base permanecen visibles durante toda la escena.
K.box(root, mapX, mapY, {w: mapW, h: mapH, style: {background: paper, border: '1px solid #8E8778', boxSizing: 'border-box'}});
const m = K.map.world(root, {x: mapX, y: mapY, w: mapW, h: mapH, projection: 'naturalEarth1', focus: [[-12, 34], [25, 61]], fill: paper, stroke: '#817C70'});

const heading = K.box(root, 130, 87, {w: 760, h: 48, cls: 'label', html: 'FRANCIA  ·  1940', style: {fontSize: '40px', color: ink, letterSpacing: '3px'}});
K.show(heading, T0 + 0.1, {from: {x: -18}, dur: 0.55, ease: 'outCubic'});
const regionTag = K.box(root, 1450, 91, {w: 330, h: 44, cls: 'label', html: 'EUROPA OCCIDENTAL', style: {fontSize: '32px', color: muted, textAlign: 'right', letterSpacing: '1px'}});
K.show(regionTag, T0 + 0.2, {from: {x: 14}, dur: 0.55, ease: 'outCubic'});

const overlay = K.svg(root, mapX, mapY, mapW, mapH);
const rng = K.rand(1940);
for (let i = 0; i < 48; i++) {
  K.shape(overlay, 'circle', {cx: 18 + rng() * 1684, cy: 14 + rng() * 562, r: 0.7 + rng() * 1.1}, {fill: '#726B5E', opacity: 0.12});
}
K.shape(overlay, 'rect', {x: 1, y: 1, width: 1718, height: 588}, {fill: 'none', stroke: '#887F6C', strokeWidth: 1});

const project = p => m.project(p);
const paris = project([2.35, 48.86]);
const rouen = project([1.1, 49.44]);
const lyon = project([4.84, 45.76]);
const brussels = project([4.35, 50.85]);
const amsterdam = project([4.9, 52.37]);
const cologne = project([6.96, 50.94]);
const roads = [];
[[rouen, paris], [paris, lyon], [brussels, paris], [amsterdam, brussels], [cologne, brussels]].forEach(([a, b]) => {
  roads.push(K.shape(overlay, 'line', {x1: a[0], y1: a[1], x2: b[0], y2: b[1]}, {stroke: '#77786F', strokeWidth: 2.2, opacity: 0.72, fill: 'none'}));
});
const cityDots = [];
[paris, rouen, lyon, brussels, amsterdam].forEach((p, i) => {
  cityDots.push(K.shape(overlay, 'circle', {cx: p[0], cy: p[1], r: i === 0 ? 6 : 4}, {fill: '#5D6465', stroke: paper, strokeWidth: 2, opacity: 0.95}));
});

const franceCenter = m.centroid('fr') || paris;
const franceTag = K.box(root, mapX + franceCenter[0] - 70, mapY + franceCenter[1] + 34, {w: 150, h: 40, cls: 'label', html: 'FRANCIA', style: {fontSize: '32px', color: ink, letterSpacing: '2px', background: 'rgba(216,208,188,0.92)', textAlign: 'center', padding: '2px 6px', boxSizing: 'border-box'}});
K.show(franceTag, T0 + 0.35, {from: {y: 8}, dur: 0.45, ease: 'outCubic'});

// Flechas de planificación dibujadas por tramos desde el este hacia Francia.
const arrowSvg = K.svg(root, mapX, mapY, mapW, mapH);
const routePts = [[10.5, 51.0], [7.5, 50.0], [5.0, 48.9], [2.35, 48.86]].map(project);
const arrows = [];
for (let i = 0; i < routePts.length - 1; i++) {
  const a = routePts[i], b = routePts[i + 1];
  const ar = K.arrow(arrowSvg, a[0], a[1], b[0], b[1], {color: K.palette.accent2, width: 6, curve: 0});
  arrows.push(ar);
  K.draw(ar, Math.min(T1 - 0.7, arrivalCue + i * 0.24), 0.48);
}

if (m.countries.fr) K.anim(m.countries.fr, franceCue, {fill: [paper, '#B87870']}, Math.min(0.75, T1 - franceCue), 'inOutSine');
['be', 'nl', 'lu'].forEach(code => {
  const path = m.countries[code];
  if (path) K.anim(path, occupiedCue, {fill: [paper, '#929895']}, Math.min(0.8, T1 - occupiedCue), 'inOutSine');
});
if (m.countries.fr) K.anim(m.countries.fr, occupiedCue, {fill: ['#B87870', '#929895']}, Math.min(0.8, T1 - occupiedCue), 'inOutSine');
[...roads, ...cityDots].forEach(el => K.anim(el, occupiedCue, {opacity: [0.72, 0.36]}, Math.min(0.8, T1 - occupiedCue), 'inOutSine'));
arrows.forEach(ar => K.anim(ar, occupiedCue, {opacity: [1, 0.38]}, Math.min(0.8, T1 - occupiedCue), 'inOutSine'));
const status = K.box(root, 1370, 91, {w: 410, h: 44, cls: 'label', html: 'BAJO OCUPACIÓN', style: {fontSize: '34px', color: K.palette.soft, textAlign: 'right', letterSpacing: '2px'}});
K.show(status, occupiedCue, {from: {y: 8}, dur: 0.55, ease: 'outCubic'});

// Baliza de avance, viva sobre el mapa hasta el final de la escena.
const beacon = K.shape(overlay, 'circle', {cx: routePts[0][0], cy: routePts[0][1], r: 6}, {fill: K.palette.accent, stroke: paper, strokeWidth: 2, opacity: 0.95});
K.show(beacon, T0 + 0.2, {from: {scale: 0.6}, dur: 0.35, ease: 'outBack'});
K.onFrame(t => {
  const a = K.clamp((t - arrivalCue) / 2.6, 0, 1);
  const scaled = a * (routePts.length - 1);
  const seg = Math.min(routePts.length - 2, Math.floor(scaled));
  const f = a >= 1 ? 1 : scaled - seg;
  const p0 = routePts[seg], p1 = routePts[seg + 1];
  const pulse = 1 + 0.12 * Math.sin(t * 2.0);
  beacon.setAttribute('cx', String(p0[0] + (p1[0] - p0[0]) * f));
  beacon.setAttribute('cy', String(p0[1] + (p1[1] - p0[1]) * f));
  beacon.setAttribute('r', String(5.5 * pulse));
  beacon.setAttribute('opacity', String(t >= occupiedCue ? 0.58 : 0.94));
});

// Línea temporal legible y persistente; seis marcas se comprimen al decir «seis».
const timelineLabel = K.box(root, 150, 779, {w: 320, h: 42, cls: 'label', html: 'PLAZO DE AVANCE', style: {fontSize: '34px', color: K.palette.soft, letterSpacing: '2px'}});
K.show(timelineLabel, T0 + 0.25, {from: {x: -12}, dur: 0.5, ease: 'outCubic'});
const timelineSvg = K.svg(root, 490, 768, 960, 72);
const baseline = K.shape(timelineSvg, 'line', {x1: 8, y1: 38, x2: 940, y2: 38}, {stroke: '#928D80', strokeWidth: 2, opacity: 0.78});
K.show(baseline, T0 + 0.35, {from: {scale: 0.96}, dur: 0.4, ease: 'outCubic'});
const marks = [];
for (let i = 0; i < 6; i++) {
  const x = 28 + i * 148;
  const mark = K.box(root, 490 + x, 793, {w: 68, h: 18, style: {background: i < 3 ? K.palette.accent2 : '#8D8B82', borderRadius: '1px'}});
  marks.push({mark, x});
  K.show(mark, T0 + 0.35 + i * 0.06, {from: {scale: 0.86, y: 4}, dur: 0.32, ease: 'outCubic'});
}
marks.forEach(({mark, x}) => {
  K.anim(mark, sixCue, {width: ['68px', '18px'], translateX: [0, 450 - x], opacity: [1, 0.82]}, Math.min(1.15, T1 - sixCue), 'inOutSine');
});

