// Costa europea en diorama 3D; los cambios de cámara siguen la pregunta y la escala del relato.
const w = K.world3d(root, T0, T1, {ground: 'europe', sky: 'plomizo', look: 'clean', haze: 5, highlight: {fr: '#7b7b7b', es: '#7b7b7b', no: '#7b7b7b'}});
