const THREE = w.THREE;
const mat = (color, roughness = 0.95) => new THREE.MeshStandardMaterial({ color, roughness, metalness: 0 });
const addBox = (x, y, z, sx, sy, sz, material, rot = 0) => {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), material);
  mesh.position.set(x, y, z); mesh.rotation.y = rot; mesh.castShadow = true; mesh.receiveShadow = true;
  w.scene.add(mesh); return mesh;
};
