const roadMat = mat('#858477');
function road3d(x1, z1, x2, z2, width) {
  const dx = x2 - x1, dz = z2 - z1;
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(Math.hypot(dx, dz), 0.12, width), roadMat);
  mesh.position.set((x1 + x2) / 2, 0.04, (z1 + z2) / 2);
  mesh.rotation.y = -Math.atan2(dz, dx); mesh.receiveShadow = true; w.scene.add(mesh);
}
