  const roof = new THREE.Mesh(new THREE.BoxGeometry(21, 1.2, 13), mat('#555d5a')); roof.position.y = 8.5; roof.castShadow = true; g.add(roof);
  g.position.set(x, 0, z); g.rotation.y = rot; w.scene.add(g);
}
