const C = K.cue;
const clampT = t => K.clamp(t, T0 + 0.02, T1 - 0.02);
const svg = K.svg(root, 0, 0, 1920, 1080);
const poly = (s, points, fill, stroke = 'none', sw = 0) => K.shape(s, 'polygon', { points, fill, stroke, 'stroke-width': sw, 'stroke-linejoin': 'round' });
const rect = (s, x, y, width, height, fill, rx = 0) => K.shape(s, 'rect', { x, y, width, height, fill, rx });
const ln = (s, x1, y1, x2, y2, stroke, sw = 2, dash = '') => K.shape(s, 'line', { x1, y1, x2, y2, stroke, 'stroke-width': sw, 'stroke-dasharray': dash, 'stroke-linecap': 'round' });

// Plomizo, calm channel; the shorelines create a clear England-to-Normandy stage.
rect(svg, 0, 0, 1920, 1080, '#35434D');
rect(svg, 0, 270, 1920, 520, '#536b75');
poly(svg, '0,270 330,270 390,410 365,790 0,790', '#777c73');
poly(svg, '1920,270 1605,270 1550,410 1580,790 1920,790', '#777c73');
poly(svg, '0,270 330,270 350,300 0,305', '#91958a');
poly(svg, '1920,270 1605,270 1584,300 1920,305', '#91958a');
// Soft water marks give the channel life without competing with the cargo.
for (let i = 0; i < 13; i++) {
  const y = 340 + i * 31;
  ln(svg, 410 + (i % 3) * 42, y, 790 + (i % 4) * 45, y, '#91a2a4', 2, '9 15');
  ln(svg, 1050 + (i % 4) * 35, y + 13, 1450 - (i % 3) * 30, y + 13, '#91a2a4', 2, '8 17');
}
// English construction yard: crane, assembly slip and concrete sections.
rect(svg, 116, 556, 224, 24, '#626e70');
for (let i = 0; i < 3; i++) {
  const x = 142 + i * 66;
  poly(svg, `${x},541 ${x+48},541 ${x+55},552 ${x-3},552`, '#c1c0b6');
  rect(svg, x, 503, 48, 38, '#a8aaa2');
  poly(svg, `${x},503 ${x+9},494 ${x+57},494 ${x+48},503`, '#d1d0c6');
  rect(svg, x + 7, 512, 34, 4, '#53616a');
}
// Crane silhouette in clean industrial tones.
rect(svg, 246, 355, 13, 151, '#657782');
rect(svg, 221, 354, 86, 10, '#657782');
poly(svg, '252,364 259,364 307,466 301,466', '#657782');
rect(svg, 285, 365, 6, 100, '#394951');
rect(svg, 281, 462, 15, 5, '#394951');
poly(svg, '227,505 278,505 278,515 227,515', '#657782');
// Shore works and distant breakwater piles.
for (let i = 0; i < 5; i++) {
  rect(svg, 74 + i * 43, 605 + (i % 2) * 12, 30, 26, '#858a84');
  poly(svg, `${74+i*43},605 ${81+i*43},598 ${111+i*43},598 ${104+i*43},605`, '#b8b8ae');
}
ln(svg, 72, 650, 350, 650, '#d4a017', 3);
// Normandy beach approach markers and a restrained destination breakwater line.
for (let i = 0; i < 5; i++) {
  const x = 1632 + i * 39;
  rect(svg, x, 571 + (i % 2) * 7, 27, 24, '#858a84');
  poly(svg, `${x},571 ${x+6},565 ${x+33},565 ${x+27},571`, '#b8b8ae');
}

// A detailed isometric caisson-and-tug unit; it crosses the channel in one continuous shot.
const convoy = K.svg(root, 0, 0, 520, 280);
// floating concrete breakwater caisson
poly(convoy, '36,118 290,118 338,145 83,145', '#d0cfc4');
poly(convoy, '83,145 338,145 338,207 83,207', '#969b96');
poly(convoy, '36,118 83,145 83,207 36,179', '#adb0a8');
poly(convoy, '47,125 278,125 314,143 82,143', '#e0ded3');
// recesses and coping stones lend depth to the concrete module
for (let i = 0; i < 5; i++) {
  rect(convoy, 105 + i * 42, 157, 23, 31, '#687780', 2);
  rect(convoy, 109 + i * 42, 161, 15, 23, '#475963', 1);
}
ln(convoy, 90, 198, 330, 198, '#d2d0c5', 4);
// tow rope
ln(convoy, 338, 163, 374, 163, '#d4a017', 3);
// tug hull, wheelhouse, funnel and wake
poly(convoy, '365,167 495,167 473,195 385,195 370,185', '#3d6ea8');
poly(convoy, '381,163 466,163 478,170 375,170', '#6d8790');
rect(convoy, 405, 133, 42, 30, '#c4c6be');
rect(convoy, 414, 139, 9, 9, '#71838a'); rect(convoy, 430, 139, 9, 9, '#71838a');
rect(convoy, 439, 118, 12, 16, '#394951');
rect(convoy, 457, 151, 8, 12, '#d4a017');
ln(convoy, 490, 204, 518, 211, '#b7c2c1', 3);
ln(convoy, 482, 211, 511, 218, '#b7c2c1', 2);

// Convoy starts near the English works, then travels steadily across the channel.
K.show(svg, T0 + 0.08, { dur: 0.5, ease: 'outCubic' });
K.show(convoy, clampT(C('remolcarlos')), { from: { x: -18, y: 8 }, dur: 0.55, ease: 'outCubic' });
K.anim(convoy, clampT(C('remolcarlos') + 0.45), { translateX: [0, 1030] }, Math.max(0.3, Math.min(2.4, (T1 - C('remolcarlos')) * 0.43)), 'inOutSine');

// Additional caissons assemble into a continuous artificial harbour off Normandy.
function addHarbourSection(x, y, i) {
  const s = K.svg(root, x, y, 150, 170);
  poly(s, '8,61 112,61 141,78 37,78', '#d0cfc4');
  poly(s, '37,78 141,78 141,132 37,132', '#969b96');
  poly(s, '8,61 37,78 37,132 8,114', '#adb0a8');
  poly(s, '18,66 108,66 127,77 37,77', '#e0ded3');
  rect(s, 52, 91, 26, 29, '#566a73', 2);
  rect(s, 84, 91, 26, 29, '#566a73', 2);
  rect(s, 43, 133, 90, 6, '#c1c0b6');
  // pontoon link between adjacent sections
  if (i < 4) rect(s, 133, 117, 17, 9, '#657782');
  K.show(s, clampT(C('montarlos') + i * 0.12), { from: { y: 24, scale: 0.94 }, dur: 0.65, ease: 'outCubic' });
  K.anim(s, clampT(C('montarlos') + 0.8), { translateY: [0, -3, 0] }, Math.min(2.6, T1 - C('montarlos') - 0.85), 'inOutSine');
}
for (let i = 0; i < 5; i++) addHarbourSection(1276 + i * 98, 472 + (i % 2) * 8, i);

const title = K.box(root, 105, 94, { w: 760, h: 60, cls: 'label', html: 'MULBERRY  /  PUERTO ARTIFICIAL', style: { fontSize: '40px', color: '#F2F0E8', letterSpacing: '2px' } });
const date = K.box(root, 108, 151, { w: 360, h: 43, cls: 'label', html: '1944  ·  CANAL DE LA MANCHA', style: { fontSize: '30px', color: '#D4A017', letterSpacing: '1px' } });
const channel = K.box(root, 742, 248, { w: 460, h: 42, cls: 'label', html: 'TRAVESÍA DEL CANAL', style: { fontSize: '32px', color: '#F2F0E8', textAlign: 'center', letterSpacing: '2px' } });
const england = K.box(root, 105, 744, { w: 330, h: 48, cls: 'label', html: 'INGLATERRA  ·  OBRA', style: { fontSize: '32px', color: '#F2F0E8', letterSpacing: '1px' } });
const normandy = K.box(root, 1495, 744, { w: 330, h: 48, cls: 'label', html: 'NORMANDÍA  ·  MONTAJE', style: { fontSize: '32px', color: '#F2F0E8', letterSpacing: '1px' } });
K.show(title, clampT(C('puertos')), { from: { y: -12 }, dur: 0.5, ease: 'outCubic' });
K.show(date, clampT(C('plan')), { from: { y: -8 }, dur: 0.45, ease: 'outCubic' });
K.show(channel, clampT(C('canal')), { from: { y: -8 }, dur: 0.45, ease: 'outCubic' });
K.show(england, T0 + 0.15, { from: { x: -12 }, dur: 0.5, ease: 'outCubic' });
K.show(normandy, clampT(C('playas')), { from: { x: 12 }, dur: 0.5, ease: 'outCubic' });
K.onFrame(t => {
  const sway = Math.sin(t * 1.1) * 1.5;
  convoy.style.transform = `translateX(${Math.max(0, Math.min(1030, (t - C('remolcarlos') - 0.45) * 420))}px) translateY(${sway}px)`;
});

