// Filas regulares de tiendas: geometría ordenada, como un campamento montado para ser visto.
const tents=[];
for(let r=0;r<4;r++)for(let c=0;c<5;c++){
  const g=sh(scene,'g',{}),x=445+c*166+r*26,y=397+r*79,sc=.68+r*.09,hw=37*sc,hh=34*sc;
  sh(g,'ellipse',{cx:x,cy:y+8*sc,rx:hw*1.28,ry:8*sc,fill:'#18232D',opacity:'.43'});
  sh(g,'polygon',{points:`${x-hw},${y} ${x},${y-hh} ${x+hw},${y} ${x+hw*.75},${y+hh*.48} ${x-hw*.72},${y+hh*.48}`,fill:(r+c)%2?C.tent:C.tent2,stroke:'#B8B19A','stroke-width':'2'});
  sh(g,'polygon',{points:`${x-hw},${y} ${x},${y-hh} ${x},${y+hh*.48} ${x-hw*.72},${y+hh*.48}`,fill:'#69736D',opacity:'.75'});
  sh(g,'line',{x1:x,y1:y-hh,x2:x,y2:y+hh*.45,stroke:C.line,'stroke-width':'2',opacity:'.72'});
