// Vehículos de lona y camiones señuelo, integrados en el campamento.
const decoys=[];
function tank(x,y,sc){
  const g=sh(scene,'g',{});
  sh(g,'ellipse',{cx:x,cy:y+17*sc,rx:49*sc,ry:10*sc,fill:'#18232D',opacity:'.42'});
  sh(g,'rect',{x:x-43*sc,y:y-2*sc,width:86*sc,height:20*sc,rx:9*sc,fill:C.tank,stroke:'#B0AA91','stroke-width':'2'});
  sh(g,'polygon',{points:`${x-30*sc},${y-5*sc} ${x-19*sc},${y-25*sc} ${x+20*sc},${y-25*sc} ${x+32*sc},${y-5*sc}`,fill:'#8A8C7B',stroke:'#B0AA91','stroke-width':'2'});
  sh(g,'rect',{x:x-5*sc,y:y-30*sc,width:43*sc,height:5*sc,rx:2*sc,fill:'#969582'});
  sh(g,'line',{x1:x-34*sc,y1:y+7*sc,x2:x+34*sc,y2:y+7*sc,stroke:'#48534E','stroke-width':3*sc});
