  sh(g,'path',{d:`M ${x-29*sc} ${y-1*sc} Q ${x} ${y-8*sc} ${x+29*sc} ${y-1*sc}`,fill:'none',stroke:'#D0C8B1','stroke-width':'1.5',opacity:'.65'});
