K.shape(sky, 'path', {d: 'M 28 165 C 56 153, 78 178, 105 165 S 153 154, 179 167 S 222 177, 245 164', fill: 'none', stroke: '#9caaa7', 'stroke-width': 2, 'stroke-linecap': 'round'});
const tideLabel = K.box(page, 790, 374, {w: 205, h: 42, cls: 'label', html: 'MAREA', style: {fontSize: '32px', color: '#6d8990', letterSpacing: '3px', textAlign: 'center'}});

const cal = K.svg(page, 72, 438, 1000, 218);
const cols = 7, cw = 1000 / cols, top = 34, rh = 36;
const weekdays = ['L', 'M', 'X', 'J', 'V', 'S', 'D'];
const dayLabels = [];
for (let c = 0; c < cols; c++) {
  const label = K.box(page, 72 + c * cw, 401, {w: cw, h: 32, cls: 'label', html: weekdays[c], style: {fontSize: '32px', color: '#758080', textAlign: 'center'}});
