  const row = Math.floor(cell / 7);
  const n = K.box(page, 72 + col * cw, 440 + row * rh, {w: cw, h: 34, cls: 'label', html: String(d), style: {fontSize: '32px', color: '#657071', textAlign: 'center', lineHeight: '34px'}});
  dates.push(n);
}
const marks = K.svg(page, 72, 438, 1000, 218);
// Tres marcas finas sugieren los pocos días que reúnen las condiciones; el día elegido se destaca después.
[[4, 0], [1, 2], [5, 4]].forEach(([col, row]) => {
  K.shape(marks, 'line', {x1: col * cw + 52, y1: top + row * rh - 5, x2: col * cw + 82, y2: top + row * rh - 5, stroke: C.accent, 'stroke-width': 4, 'stroke-linecap': 'round'});
});
