code.eltiempoempeora:
const C = K.cue;
const tDelay = C('aplazar');
const tMet = C('meteorologia');
const tStagg = C('Stagg');
const tBrief = C('breve');

// Parte de mando persistente y sobrio.
const date = K.box(root, 112, 102, { w: 520, h: 48, cls: 'label', html: 'INGLATERRA  ·  4 JUN 1944', style: { fontSize: '34px', color: 'var(--soft)', letterSpacing: '2px' } });
