const delay = K.box(root, 112, 158, { w: 390, h: 92, cls: 'title', html: '+1 DÍA', style: { fontSize: '78px', color: 'var(--ink)', letterSpacing: '1px' } });
K.show(delay, tDelay, { from: { y: 14 }, dur: 0.6, ease: 'outCubic' });

// Contenedor HTML persistente: la sala no depende de la opacidad de elementos SVG sueltos.
const room = K.box(root, 420, 180, { w: 1360, h: 640, style: { overflow: 'hidden' } });
const s = K.svg(room, 0, 0, 1360, 640);
K.show(room, T0 + 0.08, { from: { y: 10, scale: 0.99 }, dur: 0.65, ease: 'outCubic' });
const poly = (pts, fill, stroke = 'none', sw = 1) => K.shape(s, 'polygon', { points: pts, fill, stroke, strokeWidth: sw, strokeLinejoin: 'round' });
const rect = (x, y, w, h, fill, stroke = 'none', sw = 1, extra = {}) => K.shape(s, 'rect', { x, y, width: w, height: h, fill, stroke, strokeWidth: sw, ...extra });
const line = (x1, y1, x2, y2, color, sw = 2, extra = {}) => K.shape(s, 'line', { x1, y1, x2, y2, stroke: color, strokeWidth: sw, strokeLinecap: 'round', ...extra });
const ellipse = (cx, cy, rx, ry, fill, extra = {}) => K.shape(s, 'ellipse', { cx, cy, rx, ry, fill, ...extra });

// Sala de mando: pared fría, suelo y ventana lluviosa.
poly('42,42 1310,42 1310,432 42,432', '#293943', '#53616A', 2);
poly('42,432 1310,432 1360,620 0,620', '#202D36', '#53616A', 2);
poly('42,42 0,82 0,620 42,432', '#34434C');
line(72, 410, 1290, 410, '#647179', 3);
rect(82, 82, 390, 270, '#263C49', '#89969A', 8);
rect(94, 94, 366, 246, '#304754');
poly('95,256 145,215 207,246 259,190 314,230 372,168 459,220 459,340 95,340', '#445761');
poly('95,300 174,275 236,306 301,265 362,301 421,265 459,286 459,340 95,340', '#354750');
rect(269, 94, 7, 246, '#89969A');
rect(94, 216, 366, 7, '#89969A');
rect(72, 68, 410, 14, '#56636B');
rect(72, 352, 410, 13, '#56636B');

// Parte meteorológico en la pared: cielo cerrado y una estrecha apertura entre nubes.
rect(620, 76, 490, 270, '#3B464A', '#758087', 4);
rect(636, 92, 458, 238, '#D2CFBF', '#857F70', 2);
// Frentes y nubosidad esquemáticos impresos en el parte.
poly('650,116 728,104 778,127 830,111 887,128 945,107 1080,126 1080,195 650,195', '#849097');
poly('650,253 719,236 780,258 843,230 906,255 980,231 1080,250 1080,330 650,330', '#A5AAA5');
for (const [x, y, r] of [[710, 158, 1], [790, 151, 1.1], [868, 165, 0.95], [969, 150, 1.15], [1033, 169, 0.9]]) {
  ellipse(x, y, 25 * r, 12 * r, '#53636C');
  ellipse(x - 15 * r, y + 1, 15 * r, 10 * r, '#53636C');
  ellipse(x + 15 * r, y + 1, 17 * r, 10 * r, '#53636C');
}
for (let i = 0; i < 9; i++) {
  const x = 680 + i * 43;
  line(x, 181, x - 8, 197 + (i % 3) * 3, '#74838A', 2);
  line(x + 4, 278, x - 4, 294 + (i % 3) * 3, '#74838A', 2);
}
// Ventana breve despejada, se marca al oír «breve» y permanece rodeada de tormenta.
const clearBand = rect(827, 207, 166, 18, '#D4A017', 'none', 0, { opacity: 0 });
K.anim(clearBand, tBrief, { opacity: [0, 0.95], scaleX: [0.12, 1] }, 0.65, 'outCubic');
const focusRing = K.shape(s, 'ellipse', { cx: 910, cy: 216, rx: 112, ry: 42, fill: 'none', stroke: '#D4A017', strokeWidth: 4, opacity: 0 });
K.anim(focusRing, tBrief + 0.08, { opacity: [0, 1], rx: [78, 112], ry: [28, 42] }, 0.65, 'outCubic');

// Mesa, mapa de trabajo y anotación frontal.
poly('205,388 870,388 1135,472 414,472', '#5A605E', '#8A8F88', 3);
poly('414,472 1135,472 1118,501 398,501', '#35434A');
poly('279,501 304,501 288,612 261,612', '#414A4D');
poly('1037,501 1063,501 1085,612 1057,612', '#414A4D');
poly('420,393 858,393 1054,453 582,453', '#D8D3C1', '#908A78', 2);
K.shape(s, 'path', { d: 'M485 435 C543 411 586 423 625 435 S704 449 748 424 S828 418 872 435 S953 448 1012 426', fill: 'none', stroke: '#637B84', strokeWidth: 4, strokeLinecap: 'round' });
for (let i = 0; i < 8; i++) {
  const x = 534 + i * 47;
  line(x, 431, x - 9, 445 + (i % 3) * 2, '#89969A', 2);
}
const chartClear = K.shape(s, 'path', { d: 'M773 435 C823 423 875 424 923 438', fill: 'none', stroke: '#D4A017', strokeWidth: 7, strokeLinecap: 'round', opacity: 0 });
K.anim(chartClear, tBrief, { opacity: [0, 1], strokeWidth: [2, 7] }, 0.65, 'outCubic');

// Capitán Stagg como figura anónima, de espaldas y señalando el parte.
ellipse(672, 454, 70, 13, '#17232A', { opacity: 0.55 });
line(653, 389, 645, 448, '#4A555A', 18);
line(691, 389, 701, 448, '#4A555A', 18);
poly('633,284 696,284 716,393 614,393', '#59646A', '#303B41', 2);
ellipse(665, 258, 24, 29, '#586268');
line(637, 307, 602, 355, '#59646A', 14);
line(602, 355, 642, 375, '#59646A', 12);
line(693, 307, 753, 277, '#59646A', 14);
line(753, 277, 815, 218, '#59646A', 12);
ellipse(819, 215, 7, 5, '#6B7477');

// Lámpara tenue y su resplandor sobre la mesa.
line(755, 42, 755, 118, '#737C7D', 3);
poly('724,119 786,119 773,143 737,143', '#514F46', '#807B68', 2);
ellipse(755, 151, 52, 20, '#D4A017', { opacity: 0.16 });
const lampGlow = ellipse(771, 331, 238, 158, '#D4A017', { opacity: 0.07 });

const staggTag = K.box(root, 1115, 690, { w: 560, h: 43, cls: 'label', html: 'CAP. JAMES STAGG', style: { fontSize: '32px', color: 'var(--soft)', letterSpacing: '2px', textAlign: 'right' } });
K.show(staggTag, tStagg, { from: { y: 8 }, dur: 0.45 });
const partLabel = K.box(root, 1115, 738, { w: 560, h: 42, cls: 'label', html: 'PARTE METEOROLÓGICO', style: { fontSize: '32px', color: 'var(--soft)', letterSpacing: '2px', textAlign: 'right' } });
K.show(partLabel, tMet, { from: { y: 8 }, dur: 0.45 });
const clearLabel = K.box(root, 1190, 786, { w: 485, h: 42, cls: 'label', html: 'BREVE VENTANA', style: { fontSize: '34px', color: 'var(--accent)', letterSpacing: '2px', textAlign: 'right' } });
K.show(clearLabel, tBrief, { from: { y: 8 }, dur: 0.45, ease: 'outCubic' });

// Lluvia visible durante toda la escena y leve oscilación cálida de la lámpara.
const rain = [];
for (let i = 0; i < 30; i++) {
  const x = 108 + ((i * 53) % 338);
  const y = 104 + ((i * 37) % 220);
  const len = 18 + (i % 4) * 4;
  const el = line(x, y, x - 7, y + len, '#C0C9C8', 2, { opacity: 0.52 });
  rain.push({ el, x, y, len, speed: 46 + (i % 5) * 8 });
}
K.onFrame(t => {
  const elapsed = Math.max(0, t - T0);
  for (const d of rain) {
    const y = 98 + ((d.y - 98 + elapsed * d.speed) % 238);
    d.el.setAttribute('transform', `translate(0 ${y - d.y})`);
    d.el.setAttribute('opacity', String(0.42 + 0.14 * (0.5 + 0.5 * Math.sin(elapsed * 1.2 + d.x))));
  }
  lampGlow.setAttribute('opacity', String(0.055 + 0.022 * (0.5 + 0.5 * Math.sin(elapsed * 0.7))));
});

