root.style.position = 'relative';

const w = K.world3d(root, T0, T1, {ground: 'none', sky: 'plomizo', look: 'clean', haze: 6});
w.shot(T0, {x: 0, z: 8}, {dist: 72, pitch: 6, h: 11});
