w.shot(K.cue('parar'), {x: 0, z: -35}, {dist: 205, pitch: 8, h: 17, dur: 0.65});
w.drift(0.08);

const main = w.add('lcvp', [0, 0], {x: 0, z: 0, y: 0, ramp: 0, helmet: 'm1'});
const portCraft = w.add('lcvp', [0, 0], {x: -72, z: -150, y: 0, ramp: 0, helmet: 'm1'});
