w.add('warship', [0, 0], {x: 35, z: -1150, y: 0, length: 1800, turrets: 3});
w.add('balloon', [0, 0], {x: -115, z: -480, y: 190, cable: true});
w.add('balloon', [0, 0], {x: 170, z: -650, y: 225, cable: true});

const crew = [
  [-18, 18, 'arms_crossed'], [-7, 22, 'stand'], [5, 24, 'look_up'], [17, 18, 'stand'],
  [-16, 2, 'stand'], [-5, 5, 'look_up'], [7, 4, 'arms_crossed'], [17, 0, 'stand'],
  [-10, -13, 'stand'], [3, -12, 'look_up'], [14, -15, 'stand']
];
for (const [x, z, pose] of crew) {
  const p = w.person({x, y: 1, z}, {outfit: 'gi', helmet: 'm1', backpack: '#6b6a4a'});
  p.pose(T0 + 0.12, pose);
}
w.flow({x: -10, y: 8, z: -28}, {x: 10, y: 12, z: -250}, T0 + 0.18, T1, {
  color: '#AAB6BA', n: 42, spread: 22, speed: 0.42, size: 2.4, opacity: 0.2
});
w.onUpdate((t) => {
  const q = t - T0;
  main.rotation.x = 0.018 * Math.sin(q * 1.45);
  main.rotation.z = 0.012 * Math.sin(q * 1.05 + 0.5);
  main.position.y = 0.28 * Math.sin(q * 1.45);
  portCraft.rotation.x = 0.014 * Math.sin(q * 1.3 + 1.1);
  starboardCraft.rotation.x = 0.016 * Math.sin(q * 1.2 + 2.2);
});

// Capa ilustrada permanente: mantiene visible el punto de vista interior si el render 3D no cubre el encuadre.
const s = K.svg(root, 0, 0, 1920, 1080);
s.style.position = 'absolute';
s.style.left = '0';
s.style.top = '0';
s.style.width = '1920px';
s.style.height = '1080px';
s.style.zIndex = '10';
s.style.pointerEvents = 'none';
s.style.display = 'block';
