const shp = (parent, type, attrs, style) => K.shape(parent, type, attrs, style);
const path = (parent, d, fill, opacity = 1, extra = {}) => shp(parent, 'path', {d, fill, opacity, ...extra});
shp(s, 'rect', {x: 0, y: 0, width: 1920, height: 1080, fill: '#35434D'});
shp(s, 'path', {d: 'M0 0H1920V404C1630 388 1390 408 1110 397S600 411 0 393Z', fill: '#46545D'});
shp(s, 'path', {d: 'M0 376 C250 365 480 388 720 374 S1160 389 1430 373 S1700 383 1920 368 L1920 1080 L0 1080 Z', fill: '#263741'});
shp(s, 'rect', {x: 0, y: 365, width: 1920, height: 105, fill: '#AAB6BA', opacity: 0.13});

const convoy = shp(s, 'g', {});
// Siluetas de transportes y escolta recortadas contra el horizonte brumoso.
path(convoy, 'M210 406 L246 395 L295 394 L314 380 L362 380 L378 401 L414 405 L407 414 L222 414Z', '#879294', .9);
path(convoy, 'M455 418 L482 405 L527 404 L545 392 L579 392 L596 413 L629 417 L620 425 L464 425Z', '#707F83', .9);
path(convoy, 'M1330 404 L1366 392 L1410 392 L1433 378 L1475 378 L1493 400 L1530 405 L1522 414 L1342 414Z', '#879294', .9);
path(convoy, 'M1582 418 L1610 405 L1654 405 L1672 393 L1707 393 L1726 414 L1765 420 L1754 428 L1591 428Z', '#707F83', .9);
path(convoy, 'M900 412 L924 401 L956 401 L970 391 L1003 391 L1019 410 L1045 414 L1037 422 L909 422Z', '#7B898B', .82);
shp(s, 'path', {d: 'M0 438 C310 427 566 446 830 435 S1380 445 1920 429', fill: 'none', stroke: '#AAB6BA', strokeWidth: 3, opacity: .36});

const seaLines = shp(s, 'g', {});
for (let i = 0; i < 7; i++) {
  const y = 485 + i * 42;
  shp(seaLines, 'path', {d: `M${80 + i * 34} ${y} Q${270 + i * 24} ${y - 5} ${450 + i * 31} ${y + 1}`, fill: 'none', stroke: '#AAB6BA', strokeWidth: 2, opacity: .13});
  shp(seaLines, 'path', {d: `M${1220 - i * 22} ${y + 12} Q${1450 - i * 15} ${y + 5} ${1760 - i * 12} ${y + 13}`, fill: 'none', stroke: '#AAB6BA', strokeWidth: 2, opacity: .12});
}

// Interior de la Higgins: las bordas enmarcan a los soldados y dejan libre la vista al convoy.
const boat = shp(s, 'g', {});
path(boat, 'M0 452 L210 463 L365 495 L475 550 L555 642 L605 754 L640 885 L0 900Z', '#35434D', .99);
path(boat, 'M1920 452 L1710 463 L1555 495 L1445 550 L1365 642 L1315 754 L1280 885 L1920 900Z', '#35434D', .99);
path(boat, 'M0 806 L355 773 L595 817 L770 868 L960 899 L1150 868 L1325 817 L1565 773 L1920 806 L1920 1080 L0 1080Z', '#202E37', 1);
path(boat, 'M0 790 L360 758 L600 802 L780 850 L960 879 L1140 850 L1320 802 L1560 758 L1920 790 L1920 821 L1564 790 L1328 834 L1150 883 L960 912 L770 883 L592 834 L356 790 L0 822Z', '#78878A', .8);
path(boat, 'M0 828 L355 796 L591 839 L770 887 L960 916 L1150 887 L1329 839 L1565 796 L1920 828 L1920 856 L1568 824 L1336 868 L1154 918 L960 946 L766 918 L584 868 L352 824 L0 856Z', '#35434D', .9);
// Asientos laterales y equipo sin marcas identificables.
path(boat, 'M244 702 L458 681 L514 724 L293 754Z', '#4C5A5E', .95);
path(boat, 'M1676 702 L1462 681 L1406 724 L1627 754Z', '#4C5A5E', .95);

const men = shp(s, 'g', {});
function figure(cx, cy, scale, color, helmet = '#6B7778') {
  const r = 27 * scale;
