const C = K.palette;
const tUS = K.cue('estadounidenses', { fallback: T0 + 0.35 });
const tCotentin = K.cue('cotentin', { fallback: T0 + 4.9 });
const tClouds = K.cue('nubes', { fallback: T0 + 7.99 });
const tFire = K.cue('antiaereo', { fallback: T0 + 8.88 });
const tSpread = K.cue('dispersaron', { fallback: T0 + 9.36 });

// Relieve documental de fondo; la cartografía 2D superpuesta mantiene legibles
// el canal, las rutas y la península durante toda la escena.
const world = K.world3d(root, T0, T1, {
  ground: 'europe', sky: 'plomizo', look: 'clean', haze: 5,
  highlight: { fr: '#566872', gb: '#566872' }
});
world.shot(T0, [-1.3, 50.1], { dist: 760, pitch: 58, yaw: 0 });
world.shot(tCotentin, [-1.45, 49.55], { dist: 470, pitch: 55, yaw: -4, dur: 2.3 });
world.drift(0.018);

const mx = 190, my = 245, mw = 1540, mh = 570;
const panel = K.box(root, mx - 18, my - 18, { w: mw + 36, h: mh + 36, style: {
  boxSizing: 'border-box', background: 'rgba(24,35,45,.94)',
  border: '1px solid rgba(170,182,186,.52)', borderRadius: '3px',
  boxShadow: '0 22px 56px rgba(0,0,0,.34)', zIndex: 2
}});
K.show(panel, T0 + 0.04, { from: { y: 12 }, dur: 0.48, ease: 'outCubic' });

const m = K.map.world(root, {
  x: mx, y: my, w: mw, h: mh, projection: 'mercator',
  focus: [[-4.0, 48.75], [2.0, 52.15]],
  fill: '#596971', stroke: '#aab6ba'
});
const overlay = K.svg(root, mx, my, mw, mh);
const project = ll => m.project(ll);
const curveD = (a, b, bend = 0) => {
  const p = project(a), q = project(b);
  const dx = q[0] - p[0], dy = q[1] - p[1];
  return `M ${p[0]} ${p[1]} Q ${(p[0] + q[0]) / 2 - dy * bend} ${(p[1] + q[1]) / 2 + dx * bend} ${q[0]} ${q[1]}`;
};

const planned = [
  { a: [-1.36, 50.82], b: [-1.48, 49.59], bend: 0.045, width: 7 },
  { a: [-0.72, 50.72], b: [-1.20, 49.43], bend: -0.045, width: 6 }
];
planned.forEach((r, i) => {
  const p = K.shape(overlay, 'path', {
    d: curveD(r.a, r.b, r.bend), fill: 'none', stroke: '#3d6ea8',
    strokeWidth: r.width, strokeLinecap: 'round', opacity: 1
  });
  K.show(p, tUS + i * 0.2, { from: { y: 2 }, dur: 0.25, ease: 'outCubic' });
  K.draw(p, tUS + i * 0.2, 2.15);
});

const dot = (ll, color, radius, at, stroke = C.ink) => {
  const p = project(ll);
  const c = K.shape(overlay, 'circle', {
    cx: p[0], cy: p[1], r: radius, fill: color, stroke, strokeWidth: 2
  });
  K.show(c, at, { from: { scale: 0.35 }, dur: 0.48, ease: 'outCubic' });
  return p;
};
const utah = dot([-1.23, 49.40], '#4a7fb5', 9, T0 + 0.12);
const drop1 = dot([-1.48, 49.59], '#3d6ea8', 8, tUS);
const drop2 = dot([-1.20, 49.43], '#3d6ea8', 8, tUS + 0.18);

// Aviones esquemáticos pequeños para leer las rutas como formaciones aéreas.
const planeAt = (ll, at, size = 34) => {
  const p = project(ll);
  const wrap = K.box(root, mx + p[0] - size / 2, my + p[1] - size / 2, {
    w: size, h: size, style: { zIndex: 5, pointerEvents: 'none' }
  });
  K.icon(wrap, 'plane', 0, 0, size, { color: '#3d6ea8', stroke: 2.5 });
  K.show(wrap, at, { from: { x: -12, y: 5, scale: 0.75 }, dur: 0.55, ease: 'outCubic' });
  return wrap;
};
const aircraftA = planeAt([-1.42, 50.30], tUS + 0.5, 36);
const aircraftB = planeAt([-1.06, 50.12], tUS + 0.75, 36);

// Bruma baja, translúcida: vela parcialmente las trayectorias, sin ocultar el mapa.
const mistA = K.box(root, mx + 130, my + 165, { w: 660, h: 145, style: {
  zIndex: 6, pointerEvents: 'none', filter: 'blur(19px)',
  background: 'radial-gradient(ellipse, rgba(218,226,226,.27) 0%, rgba(201,211,212,.13) 48%, rgba(201,211,212,0) 78%)'
}});
const mistB = K.box(root, mx + 730, my + 235, { w: 650, h: 150, style: {
  zIndex: 6, pointerEvents: 'none', filter: 'blur(21px)',
  background: 'radial-gradient(ellipse, rgba(218,226,226,.25) 0%, rgba(201,211,212,.12) 48%, rgba(201,211,212,0) 78%)'
}});
K.show([mistA, mistB], tClouds, { from: { x: -24, y: 5 }, dur: 0.9, ease: 'inOutSine', stagger: 0.18 });
K.anim(mistA, tClouds + 0.55, { translateX: [-24, 68] }, 4.7, 'inOutSine');
K.anim(mistB, tClouds + 0.45, { translateX: [28, -58] }, 4.9, 'inOutSine');

// Destellos discretos de fuego antiaéreo, sin iconografía ni estallidos violentos.
const flakPts = [[-1.72, 49.98], [-1.03, 49.86], [-1.48, 49.30]];
flakPts.forEach((ll, i) => {
  const p = project(ll);
  const cx = p[0], cy = p[1];
  const ring = K.shape(overlay, 'circle', {
    cx, cy, r: 13, fill: 'none', stroke: '#d4a017', strokeWidth: 3, opacity: 1
  });
  const core = K.shape(overlay, 'circle', {
    cx, cy, r: 4, fill: '#d4a017', stroke: C.ink, strokeWidth: 1
  });
  K.show([ring, core], tFire + i * 0.12, { from: { scale: 0.55 }, dur: 0.42, ease: 'outCubic' });
  K.anim(ring, tFire + 0.35 + i * 0.12, { scale: [1, 1.5], opacity: [1, 0.55] }, 1.1, 'outCubic');
});

// La ruta prevista se desdobla en aterrizajes separados: las líneas y puntos
// permanecen en pantalla hasta el corte, no son una animación efímera.
const scatter = [
  { a: [-1.44, 50.30], b: [-1.83, 49.69], bend: -0.04 },
  { a: [-1.33, 50.24], b: [-0.91, 49.66], bend: 0.05 },
  { a: [-1.18, 50.19], b: [-1.13, 49.17], bend: -0.035 },
  { a: [-1.00, 50.15], b: [-1.88, 49.43], bend: 0.045 }
];
scatter.forEach((r, i) => {
  const path = K.shape(overlay, 'path', {
    d: curveD(r.a, r.b, r.bend), fill: 'none', stroke: '#3d6ea8',
    strokeWidth: 4.5, strokeLinecap: 'round', opacity: 1
  });
  K.show(path, tSpread + i * 0.1, { from: { scale: 0.98 }, dur: 0.35, ease: 'outCubic' });
  K.draw(path, tSpread + i * 0.1, 1.15);
  const end = project(r.b);
  const endDot = K.shape(overlay, 'circle', {
    cx: end[0], cy: end[1], r: 7, fill: '#3d6ea8', stroke: C.ink, strokeWidth: 1.5
  });
  K.show(endDot, tSpread + 0.72 + i * 0.08, { from: { scale: 0.3 }, dur: 0.4, ease: 'outBack' });
  planeAt(r.b, tSpread + 0.68 + i * 0.1, 30);
});
K.anim(aircraftA, tSpread, { opacity: [1, 0.45] }, 0.75, 'inOutSine');
K.anim(aircraftB, tSpread, { opacity: [1, 0.45] }, 0.75, 'inOutSine');

const year = K.box(root, 140, 102, { w: 180, h: 48, cls: 'label', html: '1944', style: {
  zIndex: 10, fontSize: '36px', color: C.accent, letterSpacing: '.12em'
}});
const heading = K.box(root, 140, 150, { w: 740, h: 58, cls: 'label', html: 'PLAN DE SALTO', style: {
  zIndex: 10, fontSize: '42px', color: C.ink, letterSpacing: '.055em'
}});
const channel = K.box(root, 220, 263, { w: 430, h: 42, cls: 'label', html: 'CANAL DE LA MANCHA', style: {
  zIndex: 8, fontSize: '30px', color: C.soft, letterSpacing: '.06em'
}});
const cotentin = K.box(root, 1370, 678, { w: 300, h: 48, cls: 'label', html: 'COTENTIN', style: {
  zIndex: 9, fontSize: '36px', color: C.ink, letterSpacing: '.08em'
}});
const utahLabel = K.box(root, mx + utah[0] + 20, my + utah[1] - 15, { w: 150, h: 42, cls: 'label', html: 'UTAH', style: {
  zIndex: 9, fontSize: '34px', color: '#78a9d1', letterSpacing: '.08em'
}});
const zoneLabel = K.box(root, mx + drop1[0] - 200, my + drop1[1] - 50, { w: 190, h: 38, cls: 'label', html: 'ZONA PREVISTA', style: {
  zIndex: 9, fontSize: '28px', color: '#78a9d1', letterSpacing: '.04em'
}});
const rule = K.el(root, 'div', { style: {
  position: 'absolute', left: '140px', top: '219px', width: '440px', height: '3px',
  background: C.accent, transformOrigin: 'left center', zIndex: 10
}});
K.show([year, heading, channel, cotentin, utahLabel, zoneLabel], T0 + 0.1, {
  from: { y: 10 }, dur: 0.5, ease: 'outCubic', stagger: 0.07
});
K.show(rule, T0 + 0.18, { from: { x: -12 }, dur: 0.4, ease: 'outCubic' });
K.anim(rule, T0 + 0.18, { scaleX: [0, 1] }, 0.4, 'outCubic');
K.anim(panel, T0 + 0.15, { translateY: [0, -4] }, T1 - T0 - 0.15, 'inOutSine');

