  const led = 0.55 + 0.35 * (0.5 + 0.5 * Math.sin(phase * 0.32));
  art.querySelectorAll('circle').forEach((c) => {
    if (c.getAttribute('fill') === '#D4A017' && Number(c.getAttribute('cy')) > 700) c.setAttribute('opacity', String(led));
  });
});

