// Keep model coordinates separate from their options: these are ground:'none' diorama positions.
function vessel(name, x, z, opts = {}) {
  const b = W.add(name, { x, z }, { y: 0, ...opts });
  if (b && b.position) {
    K.tl.add(b.position, { z: [z, z - 46], duration: K.ms(9.4), ease: 'linear' }, K.ms(T0 + 0.25));
