// Clearly visible, restrained mine markers placed outside the safe lane.
function mineMarker(x, z) {
  const g = new T.Group();
  const mat = new T.MeshStandardMaterial({ color: '#AAB6BA', roughness: 0.72, metalness: 0.18 });
  const ball = new T.Mesh(new T.SphereGeometry(15, 14, 12), mat);
  ball.position.y = 17;
  g.add(ball);
  const stem = new T.Mesh(new T.CylinderGeometry(2.5, 2.5, 12, 8), mat);
  stem.position.y = 5;
  g.add(stem);
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3;
    const spike = new T.Mesh(new T.ConeGeometry(4, 13, 6), mat);
    spike.position.set(Math.cos(a) * 17, 17, Math.sin(a) * 17);
    spike.rotation.z = Math.PI / 2;
    g.add(spike);
  }
  g.position.set(x, 0, z);
  W.scene.add(g);
}
for (let z = -1430; z <= -350; z += 180) {
  mineMarker(-245, z);
  mineMarker(245, z - 70);
}

// Faint lane guides are present from the start; they strengthen as the sweepers clear the route.
function safeLane(x, z0, z1) {
  const geo = new T.BufferGeometry().setFromPoints([
    new T.Vector3(x, 4, z0),
    new T.Vector3(x, 4, z1)
  ]);
  const mat = new T.LineBasicMaterial({ color: '#D4A017', transparent: true, opacity: 0.12 });
  const line = new T.Line(geo, mat);
  W.scene.add(line);
  K.tl.add(mat, { opacity: [0.12, 0.72], duration: K.ms(0.9), ease: 'outCubic' }, K.ms(K.cue('abriendo')));
  K.tl.add(mat, { opacity: [0.72, 0.5], duration: K.ms(2.2), ease: 'inOutSine' }, K.ms(K.cue('pasillos')));
}
