  S('rect',{x,y,width:57+(i%3)*4,height:h,rx:2,fill:i%2?'#77766F':'#908A7B',stroke:'#4A4B46','stroke-width':2});
  if(i%2===0) S('rect',{x:x+12,y:y+5,width:20,height:3,fill:'#AAA18D',opacity:0.55});
}
// Steel beach obstacles, spaced across the exposed strand.
const obstaclePositions=[[235,651,0.9],[495,624,0.8],[770,668,1.05],[1058,625,0.85],[1350,658,1.02],[1630,621,0.86]];
for(const [x,y,s] of obstaclePositions){
  const g=S('g',{transform:`translate(${x} ${y}) scale(${s})`});
