  S('circle',{cx:0,cy:0,r:5,fill:'#B2AAA0'} ,g);
}
// Non-identifiable figures: helmets, loaded packs, no facial detail or injury.
const actors=[];
function makeSoldier(x,footY,scale,phase){
  const g=S('g',{transform:`translate(${x} ${footY}) scale(${scale})`});
  const uniform='#596255', pack='#414B43', boots='#303735';
  S('path',{d:'M-15 -91 L15 -91 L20 -42 L14 -22 L-14 -22 L-20 -43 Z',fill:uniform,stroke:'#343B37','stroke-width':3},g);
  S('rect',{x:-27,y:-87,width:14,height:38,rx:4,fill:pack,stroke:'#303833','stroke-width':2},g);
  S('rect',{x:13,y:-84,width:13,height:35,rx:4,fill:pack,stroke:'#303833','stroke-width':2},g);
  S('path',{d:'M-15 -101 Q-12 -118 0 -118 Q13 -116 16 -101 L12 -96 L-12 -96 Z',fill:'#454F47',stroke:'#2E3733','stroke-width':2},g);
  S('path',{d:'M-18 -82 L-31 -55 L-23 -51 L-7 -70 M17 -82 L29 -59 L22 -54 L8 -70',fill:'none',stroke:uniform,'stroke-width':9,'stroke-linecap':'round'},g);
  const legs=S('g',{},g);
  S('path',{d:'M-9 -24 L-14 -7 L-19 0 M9 -24 L13 -7 L20 0',fill:'none',stroke:uniform,'stroke-width':10,'stroke-linecap':'round'},legs);
  S('path',{d:'M-22 0 L-7 0 M16 0 L28 0',fill:'none',stroke:boots,'stroke-width':8,'stroke-linecap':'round'},legs);
  actors.push({g,x,footY,scale,phase});
}
