const tCross=K.cue('cruzar'), tWall=K.cue('muro');
K.onFrame(t=>{
  const u=K.smooth(K.clamp((t-tCross)/(tWall-tCross),0,1));
  const crouch=K.smooth(K.clamp((t-tWall)/0.7,0,1));
  actors.forEach((a,i)=>{
    const start=a.footY;
    const end=558+(i%2)*7;
    const y=start+(end-start)*u;
    const bob=t<tWall?Math.sin(t*4.4+a.phase)*2:0;
    const sy=1-0.25*crouch;
    a.g.setAttribute('transform',`translate(${a.x+u*(i%2?12:-9)} ${y+bob}) scale(${a.scale} ${a.scale*sy})`);
  });
  const drift=Math.sin(t*0.75)*7;
  surf.setAttribute('transform',`translate(${drift} 0)`);
  waveLines.forEach((p,i)=>p.setAttribute('transform',`translate(${Math.sin(t*0.8+i)*10} ${Math.sin(t*1.05+i*0.6)*2})`));
});

