const reveal = (el, t, opts = {}) => K.show(el, t, {dur: 0.55, ease: 'outCubic', ...opts});
const opening = T0 + 0.1;

// Cielo plomizo, horizonte y tierra en capas.
reveal(add('rect', {x: 0, y: 0, width: 1920, height: 1080, fill: '#18232D'}), opening, {dur: 0.5});
reveal(add('path', {d: 'M0 480 Q250 420 510 468 T1010 448 T1500 463 T1920 430 L1920 1080 L0 1080Z', fill: '#35434D'}), opening, {dur: 0.65});
reveal(add('path', {d: 'M0 605 Q260 545 520 596 T1040 570 T1510 597 T1920 554 L1920 1080 L0 1080Z', fill: '#46534D'}), opening + 0.06, {dur: 0.65});
reveal(add('path', {d: 'M0 734 Q300 661 620 716 T1190 686 T1650 712 T1920 676 L1920 1080 L0 1080Z', fill: '#4b584b'}), opening + 0.1, {dur: 0.65});
// Camino de tierra que serpentea entre los setos.
