reveal(add('path', {d: 'M150 910 Q430 800 675 837 Q887 867 1036 765 Q1190 660 1412 707 Q1610 749 1810 631', fill: 'none', stroke: '#b0a38a', 'stroke-width': 4, 'stroke-linecap': 'round', opacity: 0.55}), opening + 0.15);

// Setos de bocage en varias profundidades: la abertura central deja descubrir la posición.
const hedgePaths = [
  ['M55 602 Q120 539 208 570 Q290 510 376 561 L425 621 L55 654Z', '#405648'],
