});
reveal(add('path', {d: 'M82 738 Q160 686 238 716 M1367 746 Q1460 687 1538 724 M1611 728 Q1700 674 1781 716', fill: 'none', stroke: '#718065', 'stroke-width': 8, opacity: 0.75}), opening + 0.2);

