// Contraataques: pequeñas columnas grises avanzan por los caminos entre setos.
function column(x, y, n) {
  const g = add('g', {transform: `translate(${x} ${y})`});
  for (let i = 0; i < n; i++) {
    const px = (i % 3) * 21 + (Math.floor(i / 3) % 2) * 9;
