const T = w.THREE;
const mat = (color, roughness = 0.84) => new T.MeshStandardMaterial({color, roughness});
const floorMat = mat('#27333C'), wallMat = mat('#35434D'), woodMat = mat('#55483A'), paperMat = mat('#C3B998'), metalMat = mat('#414B50'), phoneMat = mat('#20282C'), tankMat = mat('#737A79'), warmMat = mat('#D4A017');
function b3(x,y,z,sx,sy,sz,m){const o=new T.Mesh(new T.BoxGeometry(sx,sy,sz),m);o.position.set(x,y,z);w.scene.add(o);return o;}
