function planArrow(from, to, bend, start, delay, width) {
  const [x1, y1] = from, [x2, y2] = to;
  const dx = x2 - x1, dy = y2 - y1, len = Math.max(1, Math.hypot(dx, dy));
  const nx = -dy / len, ny = dx / len;
  const cx = (x1 + x2) / 2 + nx * bend, cy = (y1 + y2) / 2 + ny * bend;
  const line = K.rough(overlay, 'curve', [[[x1, y1], [cx, cy], [x2, y2]]], {stroke: '#b54a4a', strokeWidth: width, roughness: 1.05});
  const ux = dx / len, uy = dy / len, head = 18, half = 9;
  const arrow = K.rough(overlay, 'polygon', [[[x2, y2], [x2 - ux * head + nx * half, y2 - uy * head + ny * half], [x2 - ux * head - nx * half, y2 - uy * head - ny * half]]], {stroke: '#b54a4a', strokeWidth: width, fill: '#b54a4a', fillStyle: 'solid', roughness: 0.65});
  K.draw(line, start + delay, 0.8);
  K.draw(arrow, start + delay + 0.55, 0.25);
}
