const darkMat = new T.MeshStandardMaterial({color: '#35434a', roughness: 0.8});
const cableMat = new T.MeshStandardMaterial({color: '#a99d83', roughness: 0.9});
function block(parent, x, y, z, sx, sy, sz, mat) {
  const o = new T.Mesh(new T.BoxGeometry(sx, sy, sz), mat);
  o.position.set(x, y, z);
  o.castShadow = true;
  o.receiveShadow = true;
  parent.add(o);
  return o;
}
function makeTug(x, z) {
  const g = new T.Group();
