  scene.add(g);
  block(g, 0, 1.5, 0, 7.5, 2.8, 15, hullMat);
  block(g, 0, 3.3, 1.2, 5.4, 3.4, 6.4, cabinMat);
  block(g, 0, 5.5, 1.7, 2.2, 1.8, 2.2, darkMat);
  block(g, 0, 3.0, -5.0, 6.2, 0.45, 4.2, deckMat);
  block(g, -2.8, 3.0, 1.2, 0.3, 0.4, 4.5, edgeMat);
  block(g, 2.8, 3.0, 1.2, 0.3, 0.4, 4.5, edgeMat);
