  g.rotation.y = rot || 0;
  scene.add(g);
  block(g, 0, 0, 0, 20, 32, 15, concrete);
  block(g, 0, 15.9, 0, 20.6, 0.8, 15.6, edgeMat);
  block(g, 0, -2, -7.6, 14, 10, 0.25, insetMat);
  block(g, 0, 8, -7.6, 14, 8, 0.25, insetMat);
  block(g, 0, -11.5, -7.75, 20.2, 0.45, 0.3, edgeMat);
