const C = {sky:'#56656c', cloud:'#aab6ba', sea:'#405d68', seaLight:'#6d8286', land:'#777970', stone:'#77766d', wood:'#8c7c63', woodDark:'#514f47', crate:'#a28e6c', crateTop:'#c1aa80', crateSide:'#75684f', blue:'#3d6ea8', blueLight:'#5d83aa', dark:'#30383b', cream:'#d8d0bd', gold:'#d4a017'};
const S=(type,attrs)=>K.shape(svg,type,attrs);
const poly=(points,fill,extra={})=>S('polygon',{points,fill,...extra});
const rect=(x,y,w,h,fill,extra={})=>S('rect',{x,y,width:w,height:h,fill,...extra});
const line=(x1,y1,x2,y2,stroke,width=2,extra={})=>S('line',{x1,y1,x2,y2,stroke,'stroke-width':width,...extra});
const group=()=>S('g',{});

// Plomizo litoral visto desde el muelle, con horizonte bajo y perspectiva a nivel humano.
rect(0,0,1920,1080,'#18232d');
rect(0,0,1920,444,C.sky);
for(const [x,y,w,h,o] of [[80,120,410,45,.14],[555,170,360,34,.11],[1110,115,520,48,.13],[1510,230,330,30,.10]]) S('ellipse',{cx:x+w/2,cy:y,rx:w/2,ry:h,fill:C.cloud,opacity:o});
poly('0,423 260,408 485,425 730,405 980,420 1210,402 1470,420 1695,405 1920,416 1920,475 0,475',C.land);
// Casas bajas en la costa, al fondo.
for(const [x,y,w,h] of [[175,397,64,32],[252,389,42,42],[314,402,83,27],[1290,398,47,35],[1350,387,58,45],[1422,401,90,30],[1530,393,49,39],[1595,403,79,28]]){
 rect(x,y,w,h,'#74766f'); poly(`${x-5},${y} ${x+w/2},${y-14} ${x+w+5},${y}`,'#626a69');
}
rect(0,465,1920,395,C.sea);
