function crate(x,y,s=1){const g=group();
 K.shape(g,'polygon',{points:`${x},${y+12*s} ${x+22*s},${y} ${x+48*s},${y+9*s} ${x+25*s},${y+21*s}`,fill:C.crateTop});
 K.shape(g,'polygon',{points:`${x},${y+12*s} ${x+25*s},${y+21*s} ${x+25*s},${y+48*s} ${x},${y+37*s}`,fill:C.crateSide});
 K.shape(g,'polygon',{points:`${x+25*s},${y+21*s} ${x+48*s},${y+9*s} ${x+48*s},${y+35*s} ${x+25*s},${y+48*s}`,fill:'#75684f'});
 K.shape(g,'line',{x1:x+5*s,y1:y+17*s,x2:x+5*s,y2:y+36*s,stroke:'#d0bb91','stroke-width':1.5*s,opacity:.55});return g;}
function truck(x,y,s=1){const g=group();
 K.shape(g,'polygon',{points:`${x},${y+23*s} ${x+75*s},${y+23*s} ${x+75*s},${y+43*s} ${x},${y+43*s}`,fill:C.blue});
 K.shape(g,'rect',{x,y:y+7*s,width:48*s,height:18*s,fill:'#526878'});
 K.shape(g,'polygon',{points:`${x+48*s},${y+12*s} ${x+64*s},${y+12*s} ${x+75*s},${y+23*s} ${x+48*s},${y+23*s}`,fill:'#67777a'});
 K.shape(g,'rect',{x:x+52*s,y:y+15*s,width:11*s,height:7*s,fill:'#b6b6a6'});
 for(const wx of [x+17*s,x+61*s])K.shape(g,'circle',{cx:wx,cy:y+44*s,r:7*s,fill:C.dark});return g;}
function person(x,y,s=1){const g=group();
 K.shape(g,'circle',{cx:x,cy:y,r:5*s,fill:C.dark});
 K.shape(g,'rect',{x:x-6*s,y:y+5*s,width:12*s,height:20*s,fill:C.blue});
 K.shape(g,'line',{x1:x-3*s,y1:y+24*s,x2:x-5*s,y2:y+39*s,stroke:C.dark,'stroke-width':3*s});
 K.shape(g,'line',{x1:x+3*s,y1:y+24*s,x2:x+6*s,y2:y+39*s,stroke:C.dark,'stroke-width':3*s});
 K.shape(g,'line',{x1:x-5*s,y1:y+10*s,x2:x-12*s,y2:y+20*s,stroke:C.blue,'stroke-width':3*s});
 K.shape(g,'line',{x1:x+5*s,y1:y+10*s,x2:x+12*s,y2:y+20*s,stroke:C.blue,'stroke-width':3*s});
 K.shape(g,'rect',{x:x+8*s,y:y+7*s,width:10*s,height:9*s,fill:C.crate});return g;}
