const C = { bg: '#18232D', bg2: '#35434D', ink: '#F2F0E8', blue: '#3d6ea8', grey: '#7b7b7b', soft: '#AAB6BA', gold: '#D4A017' };

// Relieve 3D como base documental; el mapa 2D proyectado queda encima como garantía legible.
const w = K.world3d(root, T0, T1, { ground: 'europe', sky: 'plomizo', look: 'clean', haze: 4, highlight: { fr: C.blue, de: C.grey } });
w.shot(T0, [-0.5, 49.4], { dist: 1120, pitch: 57, yaw: -7 });
w.drift(0.012);
w.country('fr', T0, C.blue);
w.country('de', T0, C.grey);

const mapX = 100, mapY = 140, mapW = 1720, mapH = 610;
K.box(root, 84, 124, { w: 1752, h: 642, style: { backgroundColor: 'rgba(24,35,45,0.96)', border: '1px solid rgba(170,182,186,0.42)', boxSizing: 'border-box' } });
const m = K.map.world(root, { x: mapX, y: mapY, w: mapW, h: mapH, projection: 'naturalEarth1', focus: [[-8, 43], [16, 56]], fill: C.bg2, stroke: 'rgba(242,240,232,0.52)' });
if (m.countries.fr) m.countries.fr.setAttribute('fill', C.blue);
if (m.countries.de) m.countries.de.setAttribute('fill', C.grey);

const date = K.box(root, 126, 88, { w: 220, h: 52, cls: 'label', html: '1944', style: { fontSize: '42px', color: C.ink, letterSpacing: '3px' } });
K.show(date, T0 + 0.1, { from: { y: -10 }, dur: 0.45, ease: 'outCubic' });
const heading = K.box(root, 1460, 88, { w: 330, h: 48, cls: 'label', html: 'EUROPA OCCIDENTAL', style: { fontSize: '32px', color: C.soft, letterSpacing: '1px', textAlign: 'right' } });
K.show(heading, T0 + 0.12, { from: { y: -8 }, dur: 0.45, ease: 'outCubic' });

const card = K.box(root, 132, 174, { w: 420, h: 202, style: { opacity: 0, backgroundColor: 'rgba(24,35,45,0.94)', borderLeft: '5px solid ' + C.blue, padding: '20px 24px', boxSizing: 'border-box' } });
const count = K.box(card, 0, 0, { w: 365, h: 94, cls: 'label', html: '0', style: { fontSize: '70px', color: C.ink, lineHeight: '1.15', whiteSpace: 'nowrap' } });
const countTag = K.box(card, 2, 112, { w: 365, h: 40, cls: 'label', html: 'SOLDADOS ALIADOS', style: { fontSize: '32px', color: C.soft, letterSpacing: '1px' } });
const tMillions = K.cue('mas');
K.show(card, tMillions, { from: { x: 24, y: 8 }, dur: 0.5, ease: 'outCubic' });
K.show(countTag, tMillions + 0.1, { from: { y: 8 }, dur: 0.38, ease: 'outCubic' });
K.count(count, tMillions, 0, 2000000, { dur: 1.35, suffix: '+' });

// Columnas esquemáticas de tropas aliadas avanzan desde la costa francesa hacia el interior.
const troopSvg = K.svg(root, mapX, mapY, mapW, mapH);
const columns = [
  { p: [-0.65, 49.35], t: K.cue('desembarcado') },
  { p: [1.25, 49.55], t: K.cue('guerra') },
  { p: [3.55, 49.9], t: K.cue('nueve') },
  { p: [5.8, 50.3], t: K.cue('camino') }
];
columns.forEach((a, i) => {
  const q = m.project(a.p);
  const halo = K.shape(troopSvg, 'circle', { cx: q[0], cy: q[1], r: 22, fill: C.blue, opacity: 0.2 });
  K.show(halo, a.t, { from: { scale: 0.5 }, dur: 0.45, ease: 'outCubic' });
  const dots = [];
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 4; col++) {
      const dot = K.shape(troopSvg, 'circle', { cx: q[0] + (col - 1.5) * 10, cy: q[1] + (row - 0.5) * 12, r: 3.5, fill: C.blue, stroke: C.ink, 'stroke-width': 1.2, opacity: 0 });
      dots.push(dot);
    }
  }
  K.show(dots, a.t + 0.06, { from: { y: 5, scale: 0.6 }, dur: 0.38, ease: 'outBack', stagger: 0.035 });
});

// Línea temporal breve: solo expresa los nueve meses narrados, sin fechas añadidas.
const tNine = K.cue('nueve');
const timeTitle = K.box(root, 1280, 785, { w: 470, h: 48, cls: 'label', html: '9 MESES', style: { opacity: 0, fontSize: '38px', color: C.ink, letterSpacing: '2px' } });
const timeBase = K.box(root, 1282, 846, { w: 440, h: 7, style: { opacity: 0, backgroundColor: 'rgba(242,240,232,0.32)', borderRadius: '4px' } });
