const THREE3 = w.THREE;
function groundPlane(color, width, depth, x, z, y) {
  const mesh = new THREE3.Mesh(
    new THREE3.PlaneGeometry(width, depth),
    new THREE3.MeshStandardMaterial({ color, roughness: 0.95, metalness: 0 })
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(x, y, z);
  w.scene.add(mesh);
  return mesh;
}
groundPlane('#526773', 1800, 500, 0, -220, -0.12);
groundPlane('#9A927F', 1800, 160, 0, 100, -0.02);
groundPlane('#626D5A', 1800, 360, 0, 360, 0);
const stoneMat = new THREE3.MeshStandardMaterial({ color: '#b8b5a9', roughness: 0.9 });
for (let row = 0; row < 5; row++) {
  for (let col = 0; col < 13; col++) {
    const h = 8 + ((row * 3 + col) % 4);
    const stone = new THREE3.Mesh(new THREE3.BoxGeometry(3.3, h, 1.3), stoneMat);
    stone.position.set((col - 6) * 15 + (row % 2) * 5, h / 2, 205 + row * 16);
    w.scene.add(stone);
  }
}
w.onUpdate(t => {
  // Movimiento mínimo del mar, derivado solo del tiempo de la escena.
  const seaMesh = w.scene.children.find(o => o.geometry && o.geometry.type === 'PlaneGeometry' && o.position.z < -100);
  if (seaMesh) seaMesh.position.y = -0.12 + Math.sin(t * 0.22) * 0.018;
});

